import * as React from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { cn } from '@/lib/utils';

interface Transaction {
  id?: number;
  title: string;
  amount: number;
  category: string;
  date: string;
  user_uuid: number;
}

export const TransactionModal = ({ transaction, onSave }: { transaction: Transaction | null, onSave: (t: Transaction) => void }) => {
  const [form, setForm] = React.useState<Transaction>(
    transaction || { id: 0, title: '', amount: 0, category: '', date: new Date().toISOString().split('T')[0], user_uuid: 1 }
  );
  const [isExpense, setIsExpense] = React.useState(false); // Define se é um gasto ou uma entrada (salário)

  const handleSave = async () => {
    const requestData = {
      title: form.title,
      amount: form.amount,
      date: form.date,
      user_uuid: form.user_uuid,
    };

    try {
      const response = await fetch('http://localhost:3001/incomes', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(requestData),
      });

      if (response.ok) {
        onSave(form); // Se for sucesso, salva a transação
      } else {
        console.error('Erro ao salvar a transação');
      }
    } catch (error) {
      console.error('Erro de conexão com o backend:', error);
    }
  };

  return (
    <DialogContent>
      <DialogHeader>
        <DialogTitle>{transaction ? 'Editar Transação' : 'Nova Transação'}</DialogTitle>
      </DialogHeader>
      <div className="space-y-4">
        <Input
          placeholder="Título"
          value={form.title}
          onChange={(e) => setForm({ ...form, title: e.target.value })}
          className="shadow-sm focus:ring-2 focus:ring-blue-500"
        />
        <Input
          placeholder="Valor"
          type="number"
          value={form.amount}
          onChange={(e) => setForm({ ...form, amount: Number(e.target.value) })}
          className="shadow-sm focus:ring-2 focus:ring-blue-500"
        />
        <Input
          placeholder="Categoria"
          value={form.category}
          onChange={(e) => setForm({ ...form, category: e.target.value })}
          className="shadow-sm focus:ring-2 focus:ring-blue-500"
        />
        <Input
          type="date"
          value={form.date}
          onChange={(e) => setForm({ ...form, date: e.target.value })}
          className="shadow-sm focus:ring-2 focus:ring-blue-500"
        />
        <div className="flex space-x-4 mt-4">
          <Button
            variant={isExpense ? 'outline' : 'default'}
            className="px-4 py-2"
            onClick={() => setIsExpense(false)} // Definir como entrada (exemplo: Salário)
          >
            Entrada
          </Button>
          <Button
            variant={isExpense ? 'default' : 'outline'}
            className="px-4 py-2"
            onClick={() => setIsExpense(true)} // Definir como despesa
          >
            Gasto
          </Button>
        </div>
        <Button
          className="w-full bg-blue-600 text-white hover:bg-blue-700 transition duration-200 mt-4"
          onClick={handleSave}
        >
          {transaction ? 'Salvar Alterações' : 'Adicionar Transação'}
        </Button>
      </div>
    </DialogContent>
  );
};
